-- Lesson 10: can и can't: умею, могу, можно (4 sections, 49 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('can', 'can и can''t: умею, могу, можно', 'умения, вопросы и короткие ответы, просьбы Can you…?, разрешения Can I…?', 10, $lesson${"sections":[{"id":"able","nav":"I can swim","eyebrow":"Тема 1 · умения","title":"can — умею, могу","theory":"<p><b>can</b> — «умею, могу». После него глагол стоит в начальной форме, безо всяких окончаний, и форма одинаковая для всех.</p>\n<div class=\"formula\"><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">can</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>Форма</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>I / you / we / they</td><td><mark>can</mark></td><td>I can swim.</td></tr>\n<tr><td>he / she / it</td><td><mark>can</mark> — тоже без -s</td><td>She can drive.</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я умею плавать.</span><span class=\"en\">I <mark>can swim</mark>.</span></li>\n<li><span class=\"ru\">Она говорит на трёх языках.</span><span class=\"en\">She <mark>can speak</mark> three languages.</span><span class=\"why\">не can speaks</span></li>\n<li><span class=\"ru\">Мы можем встретиться завтра.</span><span class=\"en\">We <mark>can meet</mark> tomorrow.</span><span class=\"why\">can — не только умение, но и возможность</span></li>\n</ul>\n<h3>Как сказать, насколько хорошо</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Фраза</th><th>Значение</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>very well</td><td>очень хорошо</td><td>He can cook very well.</td></tr>\n<tr><td>quite well</td><td>довольно хорошо</td><td>I can swim quite well.</td></tr>\n<tr><td>a little / a bit</td><td>немного</td><td>She can speak French a little.</td></tr>\n<tr><td>not … at all</td><td>совсем не</td><td>I can't dance at all.</td></tr>\n</tbody></table></div>\n<h3>Что обычно умеют</h3>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Глаголы умений</h4><ul><li>swim — плавать</li><li>drive — водить машину</li><li>cook — готовить</li><li>dance — танцевать</li><li>sing — петь</li><li>draw — рисовать</li></ul></div><div class=\"ng\"><h4>И ещё</h4><ul><li>play the piano / the guitar — играть на пианино, гитаре</li><li>speak English — говорить по-английски</li><li>ride a bike — кататься на велосипеде</li><li>ski — кататься на лыжах</li></ul></div></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После can глагол без -s и без to: <span class=\"no\">She can drives.</span> <span class=\"no\">I can to swim.</span> <span class=\"yes\">She can drive. ✔</span> <span class=\"yes\">I can swim. ✔</span></span><span>«Я умею» — это can, а не know: <span class=\"no\">I know to swim.</span> <span class=\"yes\">I can swim. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 5: -s только у обычных глаголов · Урок 6: play the piano, ride a bike</span></div>","groups":[{"title":"Выберите правильную форму","items":[{"t":"choice","q":"She ___ very well.","o":["can cook","can cooks","cans cook"],"a":"can cook","ex":"После can — cook, без -s."},{"t":"choice","q":"I ___ the guitar.","o":["can play","can to play","can playing"],"a":"can play","ex":"can + play."},{"t":"choice","q":"My brother ___ a car.","o":["can drive","can drives","can driving"],"a":"can drive","ex":"can + drive."},{"t":"choice","q":"«Я немного говорю по-английски.»","o":["I can speak English a little.","I can speak a little English very.","I know speak English."],"a":"I can speak English a little.","ex":"a little — немного."},{"t":"choice","q":"«Я совсем не умею танцевать.»","o":["I can't dance at all.","I can't at all dance.","I don't can dance."],"a":"I can't dance at all.","ex":"not … at all — совсем не."}]},{"title":"Составьте предложение","items":[{"t":"input","q":"(I / swim)","a":["I can swim."],"ex":"I + can + swim.","p":"Напишите, что вы умеете"},{"t":"input","q":"(she / ride a bike)","a":["She can ride a bike."],"ex":"She + can + ride a bike.","p":"Напишите, что она умеет"},{"t":"input","q":"(they / speak Spanish)","a":["They can speak Spanish."],"ex":"They + can + speak Spanish.","p":"Напишите, что они умеют"}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Она умеет водить машину.»","a":["She can drive.","She can drive a car."],"ex":"can + drive.","p":"Переведите на английский"},{"t":"input","q":"«Я немного говорю по-английски.»","a":["I can speak English a little.","I can speak a little English."],"ex":"a little — немного.","p":"Переведите на английский"},{"t":"input","q":"«Мы можем встретиться завтра.»","a":["We can meet tomorrow."],"ex":"can + meet.","p":"Переведите на английский"}]}],"listen":{"scene":"Друзья планируют вечеринку","lines":[["Tom","I can play the guitar.","Я умею играть на гитаре."],["Anna","I can sing!","А я умею петь!"],["Tom","My brother can drive a car.","Мой брат умеет водить машину."],["Anna","My sister can cook very well.","Моя сестра очень хорошо готовит."],["Tom","So we can have a party!","Значит, мы можем устроить вечеринку!"],["Anna","Yes! Music, food and a car!","Да! Музыка, еда и машина!"]]}},{"id":"cant","nav":"can't","eyebrow":"Тема 2 · отрицание и вопрос","title":"can't и Can you…?","theory":"<p>Отрицание — <b>can't</b> (полная форма cannot). Вопрос — <b>Can</b> в начале. Никаких do и does здесь не нужно.</p>\n<div class=\"formula\"><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">can't</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span></div>\n<div class=\"formula\"><span class=\"slot be\">Can</span><span class=\"plus\">+</span><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span><span class=\"plus\">+</span><span class=\"slot\">?</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Да</th><th>Нет</th></tr></thead>\n<tbody>\n<tr><td><mark>Can</mark> you swim?</td><td>Yes, I can.</td><td>No, I can't.</td></tr>\n<tr><td><mark>Can</mark> she drive?</td><td>Yes, she can.</td><td>No, she can't.</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я не умею кататься на лыжах.</span><span class=\"en\">I <mark>can't</mark> ski.</span></li>\n<li><span class=\"ru\">Он не может прийти сегодня.</span><span class=\"en\">He <mark>can't</mark> come today.</span></li>\n<li><span class=\"ru\">Ты умеешь играть в шахматы?</span><span class=\"en\"><mark>Can</mark> you play chess?</span></li>\n<li><span class=\"ru\">Что ты умеешь готовить?</span><span class=\"en\"><mark>What can</mark> you <mark>cook</mark>?</span></li>\n</ul>\n<p>В вопросах со словом порядок такой же, как везде в курсе: сначала вопросительное слово, потом can.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">I don't can swim.</span> <span class=\"yes\">I can't swim. ✔</span></span><span><span class=\"no\">Do you can drive?</span> <span class=\"yes\">Can you drive? ✔</span></span><span>В коротком ответе только can: <span class=\"no\">Yes, I can swim.</span> <span class=\"yes\">Yes, I can. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 6, тема 3: to be или do — теперь добавился третий вариант, can</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"I ___ ski.","o":["can't","don't can","not can"],"a":"can't","ex":"Отрицание — can't."},{"t":"choice","q":"___ you help me?","o":["Can","Do","Are"],"a":"Can","ex":"Вопрос с can."},{"t":"choice","q":"Can she swim? — Yes, she ___.","o":["can","cans","does"],"a":"can","ex":"Yes, she can."},{"t":"choice","q":"Can they come tonight? — No, they ___.","o":["can't","don't","aren't"],"a":"can't","ex":"No, they can't."},{"t":"choice","q":"What ___ you play?","o":["can","do can","are"],"a":"can","ex":"What + can + you + play?"},{"t":"choice","q":"He ___ read without glasses.","o":["can't","doesn't can","can not to"],"a":"can't","ex":"can't + read."}]},{"title":"Сделайте отрицание и вопрос","items":[{"t":"input","q":"I can dance.","a":["I can't dance.","I cannot dance."],"ex":"can → can't.","p":"Сделайте отрицание"},{"t":"input","q":"She can play the piano.","a":["She can't play the piano.","She cannot play the piano."],"ex":"can → can't.","p":"Сделайте отрицание"},{"t":"input","q":"You can cook.","a":["Can you cook?"],"ex":"Can + you + cook?","p":"Превратите в вопрос"},{"t":"input","q":"He can drive a car.","a":["Can he drive a car?"],"ex":"Can + he + drive a car?","p":"Превратите в вопрос"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"I don't can swim.","w":1,"c":"can't","ex":"Отрицание — can't swim."},{"t":"fix","q":"Do you can play chess?","w":0,"c":"Can","ex":"Вопрос: Can you play chess?"},{"t":"fix","q":"She can sings very well.","w":2,"c":"sing","ex":"После can — sing."}]},{"title":"Соберите предложение","items":[{"t":"order","w":["I","to","can't","party","come","the"],"a":["I can't come to the party."],"ex":"I + can't + come + to the party."},{"t":"order","w":["you","speak","English","can"],"a":["Can you speak English?"],"ex":"Can + you + speak English?"},{"t":"order","w":["can","you","what","cook"],"a":["What can you cook?"],"ex":"What + can + you + cook?"}]}],"listen":{"scene":"Том зовёт кататься на лыжах","lines":[["Tom","Can you ski?","Ты умеешь кататься на лыжах?"],["Anna","No, I can't. But I can swim.","Нет. Зато я умею плавать."],["Tom","Can your sister ski?","А твоя сестра умеет?"],["Anna","Yes, she can. She can ski very well.","Да. Она отлично катается."],["Tom","Can she come on Saturday?","Она может поехать в субботу?"],["Anna","No, she can't. She's at work.","Нет. Она на работе."]]}},{"id":"ask","nav":"Can I…? Can you…?","eyebrow":"Тема 3 · просьбы и разрешения","title":"Can I…? — можно мне. Can you…? — сделай, пожалуйста","theory":"<p>Тот же <b>can</b> нужен для вежливых просьб и разрешений. Разница простая: <b>Can I…?</b> — про себя, <b>Can you…?</b> — про собеседника.</p>\n<div class=\"compare\"><div><span class=\"en\">Can I open the window?</span><span class=\"ru\">Можно открыть окно?</span><span class=\"small\">прошу разрешения</span></div><div><span class=\"en\">Can you open the window?</span><span class=\"ru\">Можешь открыть окно?</span><span class=\"small\">прошу сделать</span></div></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Фраза</th><th>Когда говорят</th></tr></thead>\n<tbody>\n<tr><td><mark>Can I have</mark> a coffee, please?</td><td>заказ в кафе, просьба дать</td></tr>\n<tr><td><mark>Can I</mark> ask you a question?</td><td>можно вопрос</td></tr>\n<tr><td><mark>Can you</mark> help me, please?</td><td>просьба о помощи</td></tr>\n<tr><td><mark>Can you</mark> say that again, please?</td><td>просьба повторить</td></tr>\n<tr><td><mark>Could</mark> you help me, please?</td><td>то же самое, но вежливее</td></tr>\n<tr><td>Sorry, I <mark>can't</mark>.</td><td>вежливый отказ</td></tr>\n</tbody></table></div>\n<p>Слово <b>please</b> ставят в конце или после подлежащего: Can you help me, <b>please</b>?</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Можно мне чай, пожалуйста?</span><span class=\"en\"><mark>Can I have</mark> a tea, please?</span></li>\n<li><span class=\"ru\">Можешь передать мне соль?</span><span class=\"en\"><mark>Can you pass</mark> me the salt?</span></li>\n<li><span class=\"ru\">Конечно, вот.</span><span class=\"en\">Sure, <mark>here you are</mark>.</span><span class=\"why\">так отвечают, когда что-то передают</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">Can I to have a coffee?</span> <span class=\"yes\">Can I have a coffee? ✔</span></span><span>«Я хочу» в кафе звучит грубо: лучше <span class=\"yes\">Can I have…? ✔</span> или I'd like… — это в уроке 12</span><span>Не путайте: Can I — можно мне, Can you — можешь ли ты.</span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 12: I'd like — ещё более вежливый заказ в кафе</span></div>","groups":[{"title":"Can I или Can you?","items":[{"t":"choice","q":"___ have the menu, please? (вы в кафе)","o":["Can I","Can you"],"a":"Can I","ex":"Просите для себя → Can I."},{"t":"choice","q":"___ help me with this bag? (обращаетесь к другу)","o":["Can I","Can you"],"a":"Can you","ex":"Просите собеседника → Can you."},{"t":"choice","q":"___ use your phone? (ваш разрядился)","o":["Can I","Can you"],"a":"Can I","ex":"Просите разрешения → Can I."},{"t":"choice","q":"___ repeat that, please? (не расслышали)","o":["Can I","Can you"],"a":"Can you","ex":"Просите повторить → Can you."}]},{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"«Можно мне воды, пожалуйста?»","o":["Can I have some water, please?","Can I to have water please?","I want water."],"a":"Can I have some water, please?","ex":"Can I have + some water."},{"t":"choice","q":"«Можешь помочь мне, пожалуйста?»","o":["Can you help me, please?","Can you to help me please?","Do you can help me?"],"a":"Can you help me, please?","ex":"Can you + help."},{"t":"choice","q":"— Can I sit here? — ___","o":["Sure, of course.","Yes, I can.","Yes, you do."],"a":"Sure, of course.","ex":"На просьбу отвечают «конечно», а не «Yes, I can»."}]},{"title":"Составьте просьбу","items":[{"t":"input","q":"(open the window — попросите собеседника)","a":["Can you open the window, please?","Can you open the window?"],"ex":"Can you + open the window.","p":"Составьте вежливую просьбу"},{"t":"input","q":"(have a coffee — попросите для себя)","a":["Can I have a coffee, please?","Can I have a coffee?"],"ex":"Can I have + a coffee.","p":"Составьте вежливую просьбу"}]},{"title":"Что ответить?","items":[{"t":"choice","q":"— Can you help me? — Конечно.","o":["Of course.","Yes, I do.","Yes, you can."],"a":"Of course.","ex":"Of course — конечно."},{"t":"choice","q":"— Can I sit here? — Нет, извините, тут занято.","o":["Sorry, it's taken.","No, I can't.","No, you don't."],"a":"Sorry, it's taken.","ex":"Вежливый отказ."},{"t":"choice","q":"— Can you say that again, please? — ___","o":["Sure. I said…","Yes, I can say.","No, I don't."],"a":"Sure. I said…","ex":"Просьбу повторить принимают словом Sure."}]}],"listen":{"scene":"Жаркий день в кафе","lines":[["Anna","Can I sit here?","Можно я здесь сяду?"],["Man","Yes, of course.","Да, конечно."],["Anna","It's hot in here. Can you open the window, please?","Здесь жарко. Можете открыть окно, пожалуйста?"],["Man","Sure.","Конечно."],["Waiter","Hello!","Здравствуйте!"],["Anna","Hello! Can I have a cold coffee, please?","Здравствуйте! Можно мне холодный кофе, пожалуйста?"]]}},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы урока вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"My sister ___ very well.","o":["can sing","can sings","cans sing"],"a":"can sing","ex":"Тема 1: can + sing."},{"t":"choice","q":"I ___ swim, but I can't ski.","o":["can","can to","am can"],"a":"can","ex":"Тема 1: I can swim."},{"t":"input","q":"He can drive.","a":["He can't drive.","He cannot drive."],"ex":"Тема 2: can → can't.","p":"Сделайте отрицание"},{"t":"choice","q":"___ you play the guitar? — No, I can't.","o":["Can","Do","Are"],"a":"Can","ex":"Тема 2: Can you…?"},{"t":"choice","q":"«Можно мне чай?»","o":["Can I have a tea, please?","Can you have a tea?","I can have a tea?"],"a":"Can I have a tea, please?","ex":"Тема 3: Can I have…?"},{"t":"choice","q":"«Можешь открыть дверь?»","o":["Can you open the door?","Can I open the door?","Do you can open the door?"],"a":"Can you open the door?","ex":"Тема 3: просьба к собеседнику."},{"t":"fix","q":"I don't can come tomorrow.","w":1,"c":"can't","ex":"Тема 2: can't come."},{"t":"order","w":["please","help","you","can","me"],"a":["Can you help me please?"],"ex":"Тема 3: Can + you + help me + please?"},{"t":"choice","q":"She can speak French ___.","o":["a little","a few","little bit"],"a":"a little","ex":"Тема 1: a little — немного."},{"t":"input","q":"«Я не умею танцевать.»","a":["I can't dance.","I cannot dance."],"ex":"Тема 2: can't dance.","p":"Переведите на английский"}]}],"listen":{"scene":"Учительница готовит школьный концерт","lines":[["Teacher","Who can play the piano?","Кто умеет играть на пианино?"],["Lily","I can!","Я!"],["Teacher","Great! Can you sing too?","Отлично! А петь умеешь?"],["Lily","No, I can't. But Max can.","Нет. Но Макс умеет."],["Max","Yes, I can sing, but I can't dance!","Да, петь умею, а танцевать — нет!"],["Teacher","No problem. Max can sing and Lily can play!","Не страшно. Макс поёт, а Лили играет!"]]}}]}$lesson$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, position = excluded.position, content = excluded.content, updated_at = now();

-- Lesson 11: me, him, them и артикли a / the (5 sections, 60 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('pronouns-articles', 'me, him, them и артикли a / the', 'местоимения после глагола, a / an / the, множественное число, I like it', 11, $lesson${"sections":[{"id":"obj","nav":"me · him · them","eyebrow":"Тема 1 · местоимения","title":"Call me. I know him.","theory":"<p>В уроке 2 были слова «чей»: my, mine. Теперь — местоимения, которые стоят <b>после глагола</b> или после предлога: «позвони <b>мне</b>», «я знаю <b>его</b>».</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто делает</th><th>Кого / кому</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>I</td><td><mark>me</mark> — меня, мне</td><td>Call me.</td></tr>\n<tr><td>you</td><td><mark>you</mark> — тебя, вас</td><td>I can help you.</td></tr>\n<tr><td>he</td><td><mark>him</mark> — его, ему</td><td>I know him.</td></tr>\n<tr><td>she</td><td><mark>her</mark> — её, ей</td><td>Give her the book.</td></tr>\n<tr><td>it</td><td><mark>it</mark> — его, её (о предмете)</td><td>I like it.</td></tr>\n<tr><td>we</td><td><mark>us</mark> — нас, нам</td><td>Come with us.</td></tr>\n<tr><td>they</td><td><mark>them</mark> — их, им</td><td>I often see them.</td></tr>\n</tbody></table></div>\n<div class=\"compare\"><div><span class=\"en\">He knows my sister.</span><span class=\"ru\">Он знает мою сестру.</span><span class=\"small\">he — кто делает</span></div><div><span class=\"en\">My sister knows him.</span><span class=\"ru\">Моя сестра знает его.</span><span class=\"small\">him — кого знает</span></div></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Позвони мне вечером.</span><span class=\"en\">Call <mark>me</mark> in the evening.</span></li>\n<li><span class=\"ru\">Я люблю их, они хорошие друзья.</span><span class=\"en\">I love <mark>them</mark>, they're good friends.</span></li>\n<li><span class=\"ru\">Этот фильм? Я его не видел.</span><span class=\"en\">This film? I didn't see <mark>it</mark>.</span><span class=\"why\">о предмете — it</span></li>\n<li><span class=\"ru\">Пойдём с нами!</span><span class=\"en\">Come with <mark>us</mark>!</span><span class=\"why\">после предлога — us</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После глагола — не he / she: <span class=\"no\">I know he.</span> <span class=\"yes\">I know him. ✔</span></span><span><span class=\"no\">Give the book to she.</span> <span class=\"yes\">Give the book to her. ✔</span></span><span>her бывает и «её» перед предметом: her bag — её сумка, I see her — я вижу её.</span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 2, темы 3 и 4: my / mine · Урок 5: he works — а здесь he превращается в him</span></div>","groups":[{"title":"Выберите местоимение","items":[{"t":"choice","q":"I saw Tom yesterday. I know ___ well.","o":["he","him","his"],"a":"him","ex":"После глагола → him."},{"t":"choice","q":"Anna is my friend. I often call ___.","o":["she","her","hers"],"a":"her","ex":"После глагола → her."},{"t":"choice","q":"These are my keys. Can you give ___ to me?","o":["they","them","their"],"a":"them","ex":"keys → them."},{"t":"choice","q":"We're at home. Come and visit ___!","o":["we","us","our"],"a":"us","ex":"После глагола → us."},{"t":"choice","q":"This song is great. I love ___.","o":["it","its","him"],"a":"it","ex":"О предмете → it."},{"t":"choice","q":"Can you help ___? I don't understand this task.","o":["I","me","my"],"a":"me","ex":"После глагола → me."}]},{"title":"Замените слова на местоимение","items":[{"t":"input","q":"I know Tom and Jack. → I know ___.","a":["them"],"ex":"Tom and Jack → them.","p":"Впишите одно слово","h":"Они — …"},{"t":"input","q":"She loves this city. → She loves ___.","a":["it"],"ex":"city → it.","p":"Впишите одно слово","h":"Предмет — …"},{"t":"input","q":"He often calls Maria. → He often calls ___.","a":["her"],"ex":"Maria → her.","p":"Впишите одно слово","h":"Она — …"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"I don't know she.","w":3,"c":"her","ex":"После глагола → her."},{"t":"fix","q":"Can you call I tomorrow?","w":3,"c":"me","ex":"После глагола → me."},{"t":"fix","q":"We saw they at the party.","w":2,"c":"them","ex":"После глагола → them."}]}],"listen":{"scene":"Подруги о Томе","lines":[["Anna","Do you know Tom?","Ты знаешь Тома?"],["Kate","Yes, I know him well. Why?","Да, хорошо его знаю. А что?"],["Anna","I like him!","Он мне нравится!"],["Kate","Call him!","Позвони ему!"],["Anna","No, you call him. Tell him about me!","Нет, ты позвони. Расскажи ему обо мне!"],["Kate","OK, OK. And come and visit us on Friday!","Ладно, ладно. И приходи к нам в пятницу!"]]}},{"id":"art","nav":"a · an · the","eyebrow":"Тема 2 · артикли","title":"a, an, the или ничего","theory":"<p>Артикли — маленькие слова перед предметом. В русском их нет, поэтому их легко забыть. Правило простое и его хватает на весь A1.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Что ставим</th><th>Когда</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td><mark>a / an</mark></td><td>предмет один и мы говорим о нём <b>впервые</b></td><td>I have a car.</td></tr>\n<tr><td><mark>the</mark></td><td>предмет уже известен или он один такой</td><td>The car is black.</td></tr>\n<tr><td>ничего</td><td>много предметов вообще, или общее понятие</td><td>I like cats. · Coffee is expensive.</td></tr>\n</tbody></table></div>\n<h3>a или an</h3>\n<p><b>an</b> — перед гласным звуком: an apple, an hour, an engineer. <b>a</b> — перед согласным: a book, a university («юниверсити» начинается со звука «й»).</p>\n<h3>Как это работает в разговоре</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я купил машину. Машина красная.</span><span class=\"en\">I bought <mark>a</mark> car. <mark>The</mark> car is red.</span><span class=\"why\">сначала a, потом the</span></li>\n<li><span class=\"ru\">Она врач.</span><span class=\"en\">She's <mark>a</mark> doctor.</span><span class=\"why\">профессия — всегда с a</span></li>\n<li><span class=\"ru\">Закрой дверь, пожалуйста.</span><span class=\"en\">Close <mark>the</mark> door, please.</span><span class=\"why\">дверь здесь одна, понятно какая</span></li>\n<li><span class=\"ru\">Я люблю собак.</span><span class=\"en\">I like dogs.</span><span class=\"why\">вообще все собаки — без артикля</span></li>\n<li><span class=\"ru\">Солнце светит.</span><span class=\"en\"><mark>The</mark> sun is shining.</span><span class=\"why\">солнце одно</span></li>\n</ul>\n<h3>Устойчивые случаи</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>С the</th><th>Без артикля</th></tr></thead>\n<tbody>\n<tr><td>the cinema, the theatre, the gym</td><td>home, work, school, bed</td></tr>\n<tr><td>the same</td><td>breakfast, lunch, dinner</td></tr>\n<tr><td>the left, the right</td><td>Monday, May, English, Russia</td></tr>\n</tbody></table></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Профессия — с артиклем: <span class=\"no\">I'm teacher.</span> <span class=\"yes\">I'm a teacher. ✔</span></span><span><span class=\"no\">I go to the home.</span> <span class=\"yes\">I go home. ✔</span></span><span><span class=\"no\">I like the cats.</span> — это «те самые кошки». Вообще про кошек: <span class=\"yes\">I like cats. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 5, тема 4: a перед профессией · Урок 5, тема 3: go home без предлога</span></div>","groups":[{"title":"a, an, the или ничего? («—» значит «ничего»)","items":[{"t":"choice","q":"I have ___ dog. ___ dog is very friendly.","o":["a / The","the / A","an / The"],"a":"a / The","ex":"Сначала a (впервые), потом The (уже известна)."},{"t":"choice","q":"My father is ___ engineer.","o":["a","an","—"],"a":"an","ex":"engineer начинается с гласного звука → an."},{"t":"choice","q":"Can you open ___ window, please?","o":["a","the","—"],"a":"the","ex":"Понятно, какое окно → the."},{"t":"choice","q":"I don't like ___ horror films.","o":["a","the","—"],"a":"—","ex":"Вообще все фильмы ужасов → без артикля."},{"t":"choice","q":"She goes to ___ gym twice a week.","o":["a","the","—"],"a":"the","ex":"go to the gym — устойчивое."},{"t":"choice","q":"We have ___ breakfast at 8.","o":["a","the","—"],"a":"—","ex":"have breakfast — без артикля."},{"t":"choice","q":"He works in ___ bank in the centre.","o":["a","the","—"],"a":"a","ex":"Впервые упоминаем банк → a."},{"t":"choice","q":"I'm at ___ home today.","o":["a","the","—"],"a":"—","ex":"at home — без артикля."}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"My sister is teacher.","w":3,"c":"a teacher","ex":"Перед профессией — a."},{"t":"choice","q":"«Я ложусь спать в одиннадцать.»","o":["I go to bed at eleven.","I go to the bed at eleven.","I go to a bed at eleven."],"a":"I go to bed at eleven.","ex":"go to bed — без артикля."},{"t":"fix","q":"She is an doctor.","w":2,"c":"a","ex":"doctor начинается с согласного → a."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Он врач.»","a":["He's a doctor.","He is a doctor."],"ex":"Перед профессией — a.","p":"Переведите на английский"},{"t":"input","q":"«Я люблю кофе.»","a":["I like coffee.","I love coffee."],"ex":"Вообще → без артикля.","p":"Переведите на английский"},{"t":"input","q":"«Закрой окно, пожалуйста.»","a":["Close the window, please."],"ex":"Понятно какое → the.","p":"Переведите на английский"}]}],"listen":{"scene":"Дети рассказывают о питомцах","lines":[["Tom","I have a dog.","У меня есть собака."],["Lily","I have a cat and a fish.","А у меня кошка и рыбка."],["Tom","The dog is very big and very friendly.","Собака очень большая и очень добрая."],["Lily","The cat isn't friendly. It sleeps all day.","Кошка недружелюбная. Она весь день спит."],["Tom","And the fish?","А рыбка?"],["Lily","The fish is my best friend!","Рыбка — мой лучший друг!"]]}},{"id":"plural","nav":"Множественное число","eyebrow":"Тема 3 · один и много","title":"cats, boxes, children","theory":"<div class=\"tbl\"><table>\n<thead><tr><th>Слово кончается на…</th><th>Что делаем</th><th>Примеры</th></tr></thead>\n<tbody>\n<tr><td>обычный случай</td><td>+ <mark>s</mark></td><td>cat → cats · book → books</td></tr>\n<tr><td>-s, -x, -ch, -sh, -o</td><td>+ <mark>es</mark></td><td>box → boxes · watch → watches · potato → potatoes</td></tr>\n<tr><td>согласная + y</td><td>y → <mark>ies</mark></td><td>city → cities · country → countries</td></tr>\n<tr><td>-f, -fe</td><td>f → <mark>ves</mark></td><td>knife → knives · wife → wives</td></tr>\n</tbody></table></div>\n<p>Правила те же, что для окончания -s у глаголов в уроке 5. Но есть слова, которые меняются полностью — их надо запомнить.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Один</th><th>Много</th></tr></thead>\n<tbody>\n<tr><td>a child — ребёнок</td><td><mark>children</mark></td></tr>\n<tr><td>a person — человек</td><td><mark>people</mark></td></tr>\n<tr><td>a man — мужчина</td><td><mark>men</mark></td></tr>\n<tr><td>a woman — женщина</td><td><mark>women</mark></td></tr>\n<tr><td>a foot — нога</td><td><mark>feet</mark></td></tr>\n<tr><td>a tooth — зуб</td><td><mark>teeth</mark></td></tr>\n</tbody></table></div>\n<p><b>people</b>, <b>children</b> — это уже «много», поэтому с ними идёт <b>are</b> и <b>there are</b>: There are a lot of people here.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">В парке двое детей.</span><span class=\"en\">There are two <mark>children</mark> in the park.</span></li>\n<li><span class=\"ru\">В комнате много людей.</span><span class=\"en\">There are a lot of <mark>people</mark> in the room.</span><span class=\"why\">не peoples</span></li>\n<li><span class=\"ru\">Я чищу зубы дважды в день.</span><span class=\"en\">I brush my <mark>teeth</mark> twice a day.</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">two childs</span> <span class=\"no\">peoples</span> <span class=\"yes\">two children ✔</span> <span class=\"yes\">people ✔</span></span><span>Слова во множественном числе — это «они»: <span class=\"no\">People is nice here.</span> <span class=\"yes\">People are nice here. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 5, тема 1: правила -s / -es у глаголов · Урок 2: gloves, earrings — вещи только во множественном</span></div>","groups":[{"title":"Напишите множественное число","items":[{"t":"input","q":"box →","a":["boxes"],"ex":"x → es.","p":"Напишите множественное число","h":"Кончается на x."},{"t":"input","q":"city →","a":["cities"],"ex":"согласная + y → ies.","p":"Напишите множественное число","h":"y меняется."},{"t":"input","q":"child →","a":["children"],"ex":"Особая форма.","p":"Напишите множественное число","h":"Не childs."},{"t":"input","q":"person →","a":["people"],"ex":"Особая форма.","p":"Напишите множественное число","h":"Не persons."},{"t":"input","q":"knife →","a":["knives"],"ex":"f → ves.","p":"Напишите множественное число","h":"Кончается на -ves."},{"t":"input","q":"woman →","a":["women"],"ex":"Особая форма.","p":"Напишите множественное число","h":"Меняется гласная."}]},{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"There are three ___ in the photo.","o":["childs","children","childrens"],"a":"children","ex":"child → children."},{"t":"choice","q":"A lot of ___ work in this office.","o":["people","peoples","persons"],"a":"people","ex":"people — уже множественное."},{"t":"choice","q":"How many ___ are there in your country?","o":["citys","cities","cityes"],"a":"cities","ex":"city → cities."},{"t":"choice","q":"People ___ very friendly here.","o":["is","are"],"a":"are","ex":"people = they → are."}]}],"listen":{"scene":"Мама смотрит школьное фото","lines":[["Mum","How many children are there in the photo?","Сколько детей на фото?"],["Sam","Twenty-five.","Двадцать пять."],["Mum","And how many teachers?","А учителей?"],["Sam","Two. The women on the left.","Двое. Женщины слева."],["Mum","The people in your class look very friendly.","Ребята в твоём классе выглядят очень дружелюбными."],["Sam","They are!","Так и есть!"]]}},{"id":"like","nav":"I like it","eyebrow":"Тема 4 · нравится","title":"like, love, hate + it и + -ing","theory":"<p>В уроке 4 было <b>like + -ing</b>: I like travelling. Теперь добавим местоимения: после like, love, hate может стоять и предмет, и человек, и целое занятие.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Что после</th><th>Пример</th><th>Перевод</th></tr></thead>\n<tbody>\n<tr><td>предмет / человек</td><td>I like <mark>this song</mark>. · I like <mark>him</mark>.</td><td>мне нравится песня / он</td></tr>\n<tr><td>занятие с -ing</td><td>I like <mark>cooking</mark>.</td><td>я люблю готовить</td></tr>\n<tr><td>очень</td><td>I <mark>really</mark> like it. · I love it.</td><td>очень нравится</td></tr>\n<tr><td>не нравится</td><td>I <mark>don't like</mark> it. · I <mark>hate</mark> it.</td><td>не нравится / ненавижу</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Мне нравится эта книга.</span><span class=\"en\">I like <mark>this book</mark>.</span></li>\n<li><span class=\"ru\">Мне она очень нравится.</span><span class=\"en\">I really like <mark>it</mark>.</span><span class=\"why\">книга — it</span></li>\n<li><span class=\"ru\">Он не любит рано вставать.</span><span class=\"en\">He doesn't like <mark>getting</mark> up early.</span><span class=\"why\">после like — getting</span></li>\n<li><span class=\"ru\">Они обожают путешествовать.</span><span class=\"en\">They love <mark>travelling</mark>.</span></li>\n</ul>\n<h3>Как ответить на «нравится?»</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Ответ</th></tr></thead>\n<tbody>\n<tr><td>Do you like it?</td><td>Yes, I do. / No, I don't.</td></tr>\n<tr><td>Do you like cooking?</td><td>Yes, I love it! / Not really.</td></tr>\n</tbody></table></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После like нужен объект: <span class=\"no\">I like very much.</span> <span class=\"yes\">I like it very much. ✔</span></span><span>Не путайте порядок: <span class=\"no\">I like very much this film.</span> <span class=\"yes\">I like this film very much. ✔</span></span><span><span class=\"no\">I like to getting up early.</span> <span class=\"yes\">I like getting up early. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 4, тема 3: like + -ing · Урок 6: Do you like…? и короткие ответы</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"This is my favourite song. I love ___.","o":["it","its","him"],"a":"it","ex":"Песня → it."},{"t":"choice","q":"I like ___ in the evening.","o":["read","reading","to reading"],"a":"reading","ex":"like + -ing."},{"t":"choice","q":"She doesn't like ___ up early.","o":["get","getting","gets"],"a":"getting","ex":"like + getting."},{"t":"choice","q":"Do you like this film? — Yes, I ___.","o":["do","like","am"],"a":"do","ex":"Короткий ответ: Yes, I do."},{"t":"choice","q":"«Мне очень нравится этот город.»","o":["I like this city very much.","I like very much this city.","I very like this city."],"a":"I like this city very much.","ex":"very much — в конце."}]},{"title":"Составьте предложение","items":[{"t":"input","q":"(I / love / cook)","a":["I love cooking."],"ex":"love + cooking.","p":"Составьте предложение"},{"t":"input","q":"(they / not like / get up early)","a":["They don't like getting up early.","They do not like getting up early."],"ex":"don't like + getting up early.","p":"Составьте предложение"},{"t":"input","q":"«Мне нравятся эти туфли.» (используйте them во втором предложении)","a":["I like these shoes. I really like them.","I like these shoes. I like them."],"ex":"shoes → them.","p":"Переведите на английский"}]},{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"My son hates ___ up early.","o":["get","getting","gets"],"a":"getting","ex":"hate + -ing."},{"t":"choice","q":"Do you like your new job? — Yes, I ___ it.","o":["love","am loving","like very"],"a":"love","ex":"love it — очень нравится."},{"t":"choice","q":"«Мне не нравятся эти туфли.»","o":["I don't like these shoes.","I don't like this shoes.","I am not like these shoes."],"a":"I don't like these shoes.","ex":"don't like + these shoes."},{"t":"choice","q":"She likes ___ very much.","o":["it","him it","them very"],"a":"it","ex":"like it very much."}]}],"listen":{"scene":"Вечер. Выбираем фильм","lines":[["Anna","Do you like horror films?","Ты любишь фильмы ужасов?"],["Max","No, I hate them.","Нет, ненавижу."],["Anna","What do you like?","А что любишь?"],["Max","I love comedies. And you?","Обожаю комедии. А ты?"],["Anna","I don't like films. I like reading in the evening.","Я не люблю фильмы. По вечерам я люблю читать."],["Max","OK, no film. Let's read!","Ладно, без фильма. Давай читать!"]]}},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы урока вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"I saw Anna and Max yesterday. I know ___ well.","o":["they","them","their"],"a":"them","ex":"Тема 1: после глагола → them."},{"t":"choice","q":"Can you call ___ at six?","o":["I","me","my"],"a":"me","ex":"Тема 1: после глагола → me."},{"t":"choice","q":"My mother is ___ nurse.","o":["a","an","—"],"a":"a","ex":"Тема 2: перед профессией — a."},{"t":"choice","q":"Close ___ door, please.","o":["a","the","—"],"a":"the","ex":"Тема 2: понятно какая дверь → the."},{"t":"choice","q":"I don't like ___ cold weather.","o":["a","the","—"],"a":"—","ex":"Тема 2: вообще → без артикля."},{"t":"input","q":"tooth →","a":["teeth"],"ex":"Тема 3: особая форма.","p":"Напишите множественное число","h":"Не tooths."},{"t":"choice","q":"There are five ___ in our team.","o":["persons","people","peoples"],"a":"people","ex":"Тема 3: people."},{"t":"choice","q":"She likes ___ to music in the car.","o":["listen","listening","listens"],"a":"listening","ex":"Тема 4: like + -ing."},{"t":"fix","q":"I know he very well.","w":2,"c":"him","ex":"Тема 1: после глагола → him."},{"t":"fix","q":"My brother is engineer.","w":3,"c":"an engineer","ex":"Тема 2: перед профессией — an."},{"t":"order","w":["song","I","like","really","this"],"a":["I really like this song."],"ex":"Тема 4: I + really like + this song."},{"t":"input","q":"«Дети дома.»","a":["The children are at home.","Children are at home."],"ex":"Тема 3: children → are.","p":"Переведите на английский"}]}],"listen":{"scene":"Том ищет знакомых","lines":[["Anna","I saw Kate and Max yesterday.","Вчера я видела Кейт и Макса."],["Tom","I know them! Kate is a nurse.","Я их знаю! Кейт — медсестра."],["Anna","And Max is an engineer.","А Макс — инженер."],["Tom","Can you give me their number?","Можешь дать мне их номер?"],["Anna","Sure. Call me at six.","Конечно. Позвони мне в шесть."]]}}]}$lesson$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, position = excluded.position, content = excluded.content, updated_at = now();

-- Lesson 12: Еда, кафе и покупки (5 sections, 56 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('food-cafe', 'Еда, кафе и покупки', 'что считается и что нет, some / any, I''d like, цены и числа', 12, $lesson${"sections":[{"id":"count","nav":"Что считается","eyebrow":"Тема 1 · еда","title":"an apple, но some bread","theory":"<p>Еда бывает двух видов. То, что можно посчитать поштучно — <b>an apple, two eggs</b>. То, что считают только мерами — <b>bread, milk, rice</b>: их нельзя сказать «два хлеба», можно «кусок хлеба».</p>\n<div class=\"tbl\"><table>\n<thead><tr><th></th><th>Считается</th><th>Не считается</th></tr></thead>\n<tbody>\n<tr><td>Примеры</td><td>an apple, a banana, eggs, tomatoes, sandwiches</td><td>bread, milk, water, rice, sugar, cheese, meat</td></tr>\n<tr><td>Один</td><td><mark>a / an</mark> apple</td><td>нельзя a bread → <mark>some</mark> bread</td></tr>\n<tr><td>Много</td><td>apple<mark>s</mark></td><td>форма не меняется: <mark>much</mark> bread</td></tr>\n<tr><td>Сколько?</td><td><mark>How many</mark> eggs?</td><td><mark>How much</mark> milk?</td></tr>\n</tbody></table></div>\n<h3>Слова для еды</h3>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Считаются</h4><ul><li>an apple — яблоко</li><li>a banana — банан</li><li>an egg — яйцо</li><li>a tomato — помидор</li><li>a sandwich — бутерброд</li><li>a biscuit — печенье</li><li>vegetables — овощи</li></ul></div><div class=\"ng\"><h4>Не считаются</h4><ul><li>bread — хлеб</li><li>milk — молоко</li><li>water — вода</li><li>juice — сок</li><li>rice — рис</li><li>cheese — сыр</li><li>meat — мясо</li><li>sugar — сахар</li><li>coffee / tea — кофе, чай</li></ul></div></div>\n<p>Порции считаются всегда: <b>a cup of</b> coffee, <b>a glass of</b> water, <b>a bottle of</b> juice, <b>a piece of</b> cake.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">В холодильнике есть молоко.</span><span class=\"en\">There's <mark>some</mark> milk in the fridge.</span></li>\n<li><span class=\"ru\">Я съел два яйца и немного хлеба.</span><span class=\"en\">I ate two <mark>eggs</mark> and <mark>some</mark> bread.</span></li>\n<li><span class=\"ru\">Можно чашку чая?</span><span class=\"en\">Can I have <mark>a cup of</mark> tea?</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">a bread</span> <span class=\"no\">two milks</span> <span class=\"yes\">some bread ✔</span> <span class=\"yes\">two glasses of milk ✔</span></span><span><span class=\"no\">How much eggs?</span> <span class=\"yes\">How many eggs? ✔</span></span><span>Есть исключение в кафе: <span class=\"yes\">Can I have a coffee? ✔</span> — там имеют в виду «одну чашку».</span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 6, тема 5: much и many · Урок 9, тема 2: some и any</span></div>","groups":[{"title":"Считается или нет?","items":[{"t":"choice","q":"___ apple","o":["an","some","a"],"a":"an","ex":"apple начинается с гласного → an."},{"t":"choice","q":"___ bread","o":["a","an","some"],"a":"some","ex":"bread не считается → some."},{"t":"choice","q":"___ egg","o":["an","some","much"],"a":"an","ex":"egg считается и начинается с гласного → an."},{"t":"choice","q":"___ water","o":["a","some","an"],"a":"some","ex":"water не считается → some."},{"t":"choice","q":"How ___ sugar do you take?","o":["much","many"],"a":"much","ex":"sugar не считается → much."},{"t":"choice","q":"How ___ tomatoes do we need?","o":["much","many"],"a":"many","ex":"tomatoes считаются → many."}]},{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"«стакан воды» — ___","o":["a glass of water","a water glass","some glass water"],"a":"a glass of water","ex":"a glass of + water."},{"t":"choice","q":"«кусок торта» — ___","o":["a piece of cake","a cake piece","some piece cake"],"a":"a piece of cake","ex":"a piece of + cake."},{"t":"choice","q":"I'd like ___ coffee and two sandwiches.","o":["a","many","an"],"a":"a","ex":"В кафе a coffee — одна чашка."}]},{"title":"Ещё слова о еде","items":[{"t":"choice","q":"«сыр» — ___","o":["cheese","meat","rice"],"a":"cheese","ex":"cheese — сыр."},{"t":"choice","q":"«овощи» — ___","o":["vegetables","biscuits","sandwiches"],"a":"vegetables","ex":"vegetables — овощи."},{"t":"choice","q":"«бутылка сока» — ___","o":["a bottle of juice","a juice bottle","some bottle juice"],"a":"a bottle of juice","ex":"a bottle of + juice."},{"t":"choice","q":"I had two ___ for breakfast.","o":["egg","eggs","some egg"],"a":"eggs","ex":"two + eggs."}]}],"listen":{"scene":"Мама и Кейт готовят салат","lines":[["Mum","How many tomatoes do we need?","Сколько нам нужно помидоров?"],["Kate","Three.","Три."],["Mum","And how much cheese?","А сколько сыра?"],["Kate","Not much.","Немного."],["Mum","And eggs?","А яйца?"],["Kate","Two eggs, please. And some bread.","Два яйца, пожалуйста. И немного хлеба."]]}},{"id":"some","nav":"some · any · a lot of","eyebrow":"Тема 2 · сколько","title":"some, any, a lot of, not much","theory":"<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Когда</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td><mark>some</mark></td><td>утверждение: немного, несколько</td><td>We have some bread.</td></tr>\n<tr><td><mark>any</mark></td><td>отрицание и вопрос</td><td>We don't have any bread. · Do we have any bread?</td></tr>\n<tr><td><mark>a lot of</mark></td><td>много — и со считаемым, и с несчитаемым</td><td>There are a lot of people. · I drink a lot of water.</td></tr>\n<tr><td><mark>not much / not many</mark></td><td>мало</td><td>I don't eat much meat. · There aren't many shops.</td></tr>\n<tr><td><mark>a few / a little</mark></td><td>немного: a few яблок, a little молока</td><td>a few apples · a little milk</td></tr>\n</tbody></table></div>\n<p>Исключение: в вежливой просьбе и предложении говорят <b>some</b>, даже в вопросе: Can I have <b>some</b> water? Would you like <b>some</b> tea?</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">У нас нет молока.</span><span class=\"en\">We don't have <mark>any</mark> milk.</span></li>\n<li><span class=\"ru\">У меня есть немного времени.</span><span class=\"en\">I have <mark>a little</mark> time.</span></li>\n<li><span class=\"ru\">В холодильнике много овощей.</span><span class=\"en\">There are <mark>a lot of</mark> vegetables in the fridge.</span></li>\n<li><span class=\"ru\">Хотите чаю?</span><span class=\"en\">Would you like <mark>some</mark> tea?</span><span class=\"why\">предложение — тоже some</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">I don't have some money.</span> <span class=\"yes\">I don't have any money. ✔</span></span><span><span class=\"no\">a few milk</span> <span class=\"yes\">a little milk ✔</span> — a few только для того, что считается</span><span>«много» в вопросе и отрицании: <span class=\"yes\">Do you drink much coffee? ✔</span> <span class=\"yes\">I don't eat many sweets. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 3, тема 2: any · Урок 9, тема 2: some и any с there is</span></div>","groups":[{"title":"Выберите слово","items":[{"t":"choice","q":"There isn't ___ juice in the bottle.","o":["some","any","a"],"a":"any","ex":"Отрицание → any."},{"t":"choice","q":"Do we need ___ eggs?","o":["some","any","a"],"a":"any","ex":"Вопрос → any."},{"t":"choice","q":"I bought ___ cheese and tomatoes.","o":["some","any","much"],"a":"some","ex":"Утверждение → some."},{"t":"choice","q":"Can I have ___ water, please?","o":["some","any","many"],"a":"some","ex":"Вежливая просьба → some."},{"t":"choice","q":"She drinks ___ coffee every day.","o":["a lot of","many","a few"],"a":"a lot of","ex":"coffee не считается → a lot of."},{"t":"choice","q":"I have ___ friends in Moscow.","o":["a little","a few","much"],"a":"a few","ex":"friends считаются → a few."}]},{"title":"Сделайте отрицание","items":[{"t":"input","q":"We have some bread.","a":["We don't have any bread.","We do not have any bread."],"ex":"some → any в отрицании.","p":"Сделайте отрицание"},{"t":"input","q":"There is some milk in the fridge.","a":["There isn't any milk in the fridge.","There is not any milk in the fridge."],"ex":"There isn't any milk.","p":"Сделайте отрицание"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"I don't have some money.","w":3,"c":"any","ex":"В отрицании → any."},{"t":"choice","q":"«В стакане немного молока.»","o":["There is a little milk in the glass.","There are a few milk in the glass.","There is a few milk in the glass."],"a":"There is a little milk in the glass.","ex":"milk не считается → a little, и there is."},{"t":"fix","q":"How much apples do you want?","w":1,"c":"many","ex":"apples считаются → many."}]}],"listen":{"scene":"Составляем список покупок","lines":[["Tom","Do we need any milk?","Нам нужно молоко?"],["Anna","Yes, we need some milk. There isn't any in the fridge.","Да, нужно. В холодильнике его нет."],["Tom","And juice?","А сок?"],["Anna","We've got a lot of juice.","Сока у нас много."],["Tom","Do we need any eggs?","Яйца нужны?"],["Anna","Yes, some eggs and some cheese.","Да, яйца и сыр."]]}},{"id":"cafe","nav":"В кафе","eyebrow":"Тема 3 · разговор","title":"I'd like… — заказ в кафе","theory":"<p><b>I'd like</b> = I would like — «я бы хотел». Это вежливый способ заказать или попросить. Звучит мягче, чем I want.</p>\n<div class=\"formula\"><span class=\"slot be\">I'd like</span><span class=\"plus\">+</span><span class=\"slot\">что</span><span class=\"plus\">+</span><span class=\"slot\">please</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Фраза</th><th>Перевод</th></tr></thead>\n<tbody>\n<tr><td><mark>I'd like</mark> a coffee, please.</td><td>Мне, пожалуйста, кофе.</td></tr>\n<tr><td><mark>Can I have</mark> the menu, please?</td><td>Можно меню?</td></tr>\n<tr><td><mark>Would you like</mark> anything else?</td><td>Хотите что-нибудь ещё?</td></tr>\n<tr><td><mark>How much is</mark> it?</td><td>Сколько это стоит?</td></tr>\n<tr><td>Here you are.</td><td>Вот, пожалуйста.</td></tr>\n<tr><td>That's £4.50.</td><td>С вас 4 фунта 50.</td></tr>\n</tbody></table></div>\n<h3>Как проходит разговор</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">— Здравствуйте, что будете?</span><span class=\"en\">— Hello, <mark>what would you like</mark>?</span></li>\n<li><span class=\"ru\">— Мне, пожалуйста, чай и бутерброд.</span><span class=\"en\">— <mark>I'd like</mark> a tea and a sandwich, please.</span></li>\n<li><span class=\"ru\">— Что-нибудь ещё?</span><span class=\"en\">— <mark>Anything else</mark>?</span></li>\n<li><span class=\"ru\">— Нет, спасибо. Сколько с меня?</span><span class=\"en\">— No, thanks. <mark>How much is</mark> that?</span></li>\n</ul>\n<p>После <b>I'd like</b> может идти и глагол — с <b>to</b>: I'd like <b>to</b> book a table. Это отличается от like + -ing из урока 4: I like cooking — вообще люблю, I'd like to cook — хочу сейчас.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">I'd like a coffee please?</span> — это не вопрос, точка в конце: <span class=\"yes\">I'd like a coffee, please. ✔</span></span><span><span class=\"no\">I want a coffee.</span> — понятно, но невежливо. Лучше <span class=\"yes\">I'd like a coffee. ✔</span></span><span><span class=\"no\">I'd like to a coffee.</span> <span class=\"yes\">I'd like a coffee. ✔</span> — to нужно только перед глаголом</span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 10, тема 3: Can I have…? · Урок 4, тема 3: like + -ing</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"«Мне, пожалуйста, чай.»","o":["I'd like a tea, please.","I like a tea, please.","I'd like to a tea."],"a":"I'd like a tea, please.","ex":"I'd like + a tea."},{"t":"choice","q":"«Я бы хотел забронировать столик.»","o":["I'd like to book a table.","I'd like book a table.","I like booking a table."],"a":"I'd like to book a table.","ex":"Перед глаголом — to."},{"t":"choice","q":"— Would you like anything else? — ___","o":["No, thanks.","Yes, I like.","No, I don't like."],"a":"No, thanks.","ex":"Вежливый отказ: No, thanks."},{"t":"choice","q":"«Сколько это стоит?»","o":["How much is it?","How many is it?","How much it is?"],"a":"How much is it?","ex":"How much + is + it?"},{"t":"choice","q":"Официант даёт вам заказ и говорит: ___","o":["Here you are.","Here it is you.","Take you."],"a":"Here you are.","ex":"Here you are — вот, пожалуйста."}]},{"title":"Составьте фразу","items":[{"t":"input","q":"(I'd like / a coffee and a sandwich)","a":["I'd like a coffee and a sandwich.","I would like a coffee and a sandwich."],"ex":"I'd like + a coffee and a sandwich.","p":"Закажите в кафе"},{"t":"input","q":"В кафе вы поели и хотите расплатиться.","a":["Can I have the bill, please?"],"ex":"Can I have + the bill.","p":"Попросите счёт: «Можно счёт, пожалуйста?»"},{"t":"order","w":["like","water","of","a","i'd","glass"],"a":["I'd like a glass of water."],"ex":"I'd like + a glass of water."}]},{"title":"Соберите диалог в кафе","items":[{"t":"input","q":"— What would you like?","a":["I'd like a tea and a piece of cake, please.","I would like a tea and a piece of cake, please."],"ex":"I'd like + a tea and a piece of cake.","p":"Ответьте: «Мне, пожалуйста, чай и кусок торта.»"},{"t":"input","q":"— Anything else?","a":["No, thanks.","No, thank you."],"ex":"No, thanks.","p":"Ответьте: «Нет, спасибо.»"},{"t":"input","q":"Официант принёс заказ.","a":["How much is that altogether?","How much is it altogether?","How much is that?"],"ex":"How much is that altogether?","p":"Спросите: «Сколько всего?»"}]}],"listen":{"scene":"Анна заказывает в кафе","lines":[["Waiter","Hello! What would you like?","Здравствуйте! Что будете заказывать?"],["Anna","I'd like a tea and a piece of cake, please.","Мне чай и кусок торта, пожалуйста."],["Waiter","Anything else?","Что-нибудь ещё?"],["Anna","A glass of water, please.","Стакан воды, пожалуйста."],["Waiter","Here you are.","Пожалуйста."],["Anna","Thank you. Can I have the bill, please?","Спасибо. Можно счёт, пожалуйста?"]]}},{"id":"money","nav":"Цены и числа","eyebrow":"Тема 4 · покупки","title":"How much is it? Числа до тысячи","theory":"<div class=\"tbl\"><table>\n<thead><tr><th>Число</th><th>Слово</th><th>Число</th><th>Слово</th></tr></thead>\n<tbody>\n<tr><td>60</td><td>sixty</td><td>100</td><td>a hundred</td></tr>\n<tr><td>70</td><td>seventy</td><td>200</td><td>two hundred</td></tr>\n<tr><td>80</td><td>eighty</td><td>1 000</td><td>a thousand</td></tr>\n<tr><td>90</td><td>ninety</td><td>2 500</td><td>two thousand five hundred</td></tr>\n</tbody></table></div>\n<p>Между сотнями и остатком ставят <b>and</b>: 125 — one hundred <b>and</b> twenty-five. Помните про -teen и -ty из урока 5: thirteen и thirty звучат по-разному.</p>\n<h3>Цены</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Когда</th></tr></thead>\n<tbody>\n<tr><td><mark>How much is</mark> this bag?</td><td>один предмет</td></tr>\n<tr><td><mark>How much are</mark> these shoes?</td><td>несколько предметов</td></tr>\n<tr><td><mark>How much is</mark> that altogether?</td><td>сколько всего</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Сколько стоит эта футболка? — 15 фунтов.</span><span class=\"en\">How much is this T-shirt? — It's £15.</span><span class=\"why\">£ — фунт, $ — доллар, € — евро</span></li>\n<li><span class=\"ru\">Сколько стоят эти билеты? — По 20 евро каждый.</span><span class=\"en\">How much are the tickets? — €20 each.</span></li>\n<li><span class=\"ru\">Это слишком дорого.</span><span class=\"en\">That's too expensive.</span><span class=\"why\">too — слишком</span></li>\n</ul>\n<h3>Слова про покупки</h3>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Магазин</h4><ul><li>shop — магазин</li><li>supermarket — супермаркет</li><li>market — рынок</li><li>bill — счёт</li><li>receipt — чек</li><li>cash — наличные</li><li>card — карта</li></ul></div><div class=\"ng\"><h4>Оценка</h4><ul><li>cheap — дешёвый</li><li>expensive — дорогой</li><li>free — бесплатный</li><li>each — за штуку</li><li>altogether — всего</li></ul></div></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">How much cost this bag?</span> <span class=\"yes\">How much is this bag? ✔</span> <span class=\"yes\">How much does this bag cost? ✔</span></span><span><span class=\"no\">two hundreds</span> <span class=\"yes\">two hundred ✔</span></span><span><span class=\"no\">It's very expensive too.</span> <span class=\"yes\">It's too expensive. ✔</span> — too ставится перед прилагательным</span></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 5, тема 5: числа до 50 · Урок 6, тема 5: How much и How many</span></div>","groups":[{"title":"Числа и цены","items":[{"t":"input","q":"70 →","a":["seventy"],"ex":"70 = seventy.","p":"Напишите число словами","h":"Начинается на sev."},{"t":"input","q":"90 →","a":["ninety"],"ex":"90 = ninety.","p":"Напишите число словами","h":"Начинается на nin."},{"t":"input","q":"250 →","a":["two hundred and fifty","two hundred fifty"],"ex":"two hundred + and + fifty.","p":"Напишите число словами","h":"two hundred and…"},{"t":"choice","q":"___ is this jacket? — It's £40.","o":["How much","How many","How much does"],"a":"How much","ex":"Цена одного предмета → How much is."},{"t":"choice","q":"How much ___ these shoes?","o":["is","are","do"],"a":"are","ex":"shoes — несколько → are."},{"t":"choice","q":"«Это слишком дорого.»","o":["It's too expensive.","It's expensive too.","It's very expensive too."],"a":"It's too expensive.","ex":"too — перед прилагательным."}]},{"title":"Выберите слово","items":[{"t":"choice","q":"«наличные» — ___","o":["cash","card","bill"],"a":"cash","ex":"cash — наличные."},{"t":"choice","q":"«счёт в кафе» — ___","o":["bill","receipt","cheap"],"a":"bill","ex":"bill — счёт."},{"t":"choice","q":"Эти яблоки по 50 пенсов ___.","o":["each","altogether","free"],"a":"each","ex":"each — за штуку."}]}],"listen":{"scene":"Магазин одежды","lines":[["Anna","How much is this jacket?","Сколько стоит эта куртка?"],["Seller","It's forty pounds.","Сорок фунтов."],["Anna","And these shoes?","А эти туфли?"],["Seller","They're sixty pounds.","Шестьдесят фунтов."],["Anna","Sixty? That's a lot of money!","Шестьдесят? Это много денег!"],["Seller","But they're very beautiful!","Зато они очень красивые!"]]}},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы урока вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"Can I have ___ apple, please?","o":["a","an","some"],"a":"an","ex":"Тема 1: apple → an."},{"t":"choice","q":"There isn't ___ bread at home.","o":["some","any","a"],"a":"any","ex":"Тема 2: отрицание → any."},{"t":"choice","q":"How ___ water do you drink every day?","o":["much","many"],"a":"much","ex":"Тема 1: water не считается → much."},{"t":"choice","q":"I have ___ friends here.","o":["a little","a few"],"a":"a few","ex":"Тема 2: friends считаются → a few."},{"t":"choice","q":"«Мне, пожалуйста, сок.»","o":["I'd like a juice, please.","I like a juice please.","I'd like to a juice."],"a":"I'd like a juice, please.","ex":"Тема 3: I'd like."},{"t":"input","q":"Вы закончили обед в кафе.","a":["Can I have the bill, please?"],"ex":"Тема 3: Can I have the bill.","p":"Попросите счёт: «Можно счёт, пожалуйста?»"},{"t":"choice","q":"How much ___ these tomatoes?","o":["is","are","does"],"a":"are","ex":"Тема 4: tomatoes → are."},{"t":"input","q":"80 →","a":["eighty"],"ex":"Тема 4: 80 = eighty.","p":"Напишите число словами","h":"Начинается на eig."},{"t":"fix","q":"How much apples do we need?","w":1,"c":"many","ex":"Тема 1: apples считаются → many."},{"t":"order","w":["like","cup","a","of","tea","i'd"],"a":["I'd like a cup of tea."],"ex":"Тема 3: I'd like + a cup of tea."},{"t":"choice","q":"We need ___ milk and three eggs.","o":["some","any","a"],"a":"some","ex":"Тема 2: утверждение → some."},{"t":"input","q":"«Сколько стоит эта сумка?»","a":["How much is this bag?","How much does this bag cost?"],"ex":"Тема 4: How much is…?","p":"Переведите на английский"}]}],"listen":{"scene":"Завтрак. Том голодный","lines":[["Tom","Is there any bread?","Хлеб есть?"],["Mum","No, there isn't any bread at home.","Нет, дома хлеба нет."],["Tom","Can I have an apple, please?","Можно мне яблоко?"],["Mum","Here you are. How much water do you drink every day?","Держи. Сколько воды ты пьёшь каждый день?"],["Tom","Not much. A few glasses.","Немного. Пару стаканов."],["Mum","Drink more!","Пей больше!"]]}}]}$lesson$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, position = excluded.position, content = excluded.content, updated_at = now();

-- Lesson 13: Тексты: читаем и переводим (6 sections, 66 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('texts', 'Тексты: читаем и переводим', 'короткие тексты по темам курса, вопросы на понимание и перевод', 13, $lesson${"steps":false,"sections":[{"id":"about","nav":"Текст 1 · о себе","eyebrow":"Текст 1 · уроки 1–2","title":"About me","theory":"<p>Прочитайте текст. Незнакомые слова — в списке под ним. Потом ответьте на вопросы и переведите предложения.</p>\n<h3>Marina, 29</h3>\n<div class=\"reading\"><p>Hello! My <b>name's</b> Marina and <b>I'm</b> from Kazan. <b>I'm</b> 29 years old and <b>I'm</b> a nurse. I work in a small hospital near my house.</p><p>I live with my husband and our daughter. Her <b>name's</b> Vera and <b>she's</b> six. My husband is an engineer. <b>He's</b> from Samara, so <b>he's</b> Russian too.</p><p>My favourite month is May, because the weather is warm and my birthday is on the 12th of May. <b>I'm</b> interested in photography, but <b>I'm</b> not very good at it!</p></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Новые слова</h4><ul><li>a nurse — медсестра</li><li>a hospital — больница</li><li>a husband — муж</li><li>a daughter — дочь</li><li>because — потому что</li><li>warm — тёплый</li><li>good at — хорош в чём-то</li></ul></div></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 1: to be, страны и национальности · Урок 2: чьё это · Урок 4: месяцы</span></div>","groups":[{"title":"Правда или нет?","items":[{"t":"choice","q":"Marina is a doctor.","o":["True","False"],"a":"False","ex":"She's a nurse — медсестра."},{"t":"choice","q":"She lives in Kazan.","o":["True","False"],"a":"True","ex":"I'm from Kazan, I work near my house."},{"t":"choice","q":"Her daughter is six years old.","o":["True","False"],"a":"True","ex":"Her name's Vera and she's six."},{"t":"choice","q":"Her husband is from Kazan.","o":["True","False"],"a":"False","ex":"He's from Samara."},{"t":"choice","q":"Marina is a good photographer.","o":["True","False"],"a":"False","ex":"I'm not very good at it."}]},{"title":"Ответьте по тексту","items":[{"t":"choice","q":"How old is Marina?","o":["She's 29.","She's 6.","She's 12."],"a":"She's 29.","ex":"I'm 29 years old."},{"t":"choice","q":"What does her husband do?","o":["He's an engineer.","He's a nurse.","He's a photographer."],"a":"He's an engineer.","ex":"My husband is an engineer."},{"t":"choice","q":"When is her birthday?","o":["In May.","In March.","In June."],"a":"In May.","ex":"my birthday is on the 12th of May."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Меня зовут Марина, я из Казани.»","a":["My name's Marina and I'm from Kazan.","My name is Marina and I am from Kazan.","My name is Marina, I'm from Kazan."],"ex":"My name's… and I'm from…","p":"Переведите на английский"},{"t":"input","q":"«Я медсестра.»","a":["I'm a nurse.","I am a nurse."],"ex":"Перед профессией — a.","p":"Переведите на английский"},{"t":"input","q":"«Мой муж инженер.»","a":["My husband is an engineer.","My husband's an engineer."],"ex":"engineer → an.","p":"Переведите на английский"},{"t":"input","q":"«Мой день рождения в мае.»","a":["My birthday is in May."],"ex":"in + месяц.","p":"Переведите на английский"}]}]},{"id":"flat","nav":"Текст 2 · квартира","eyebrow":"Текст 2 · урок 9","title":"Our flat","theory":"<h3>Our flat</h3>\n<div class=\"reading\"><p>We live in a small flat on the fourth floor. <b>There are</b> three rooms: a living room, a bedroom and a kitchen.</p><p><b>There's</b> a big sofa in the living room and a lamp <b>next to</b> it. Our TV is <b>on</b> the wall, <b>opposite</b> the sofa. <b>There isn't</b> a table in this room, so we have dinner in the kitchen.</p><p>Our building is <b>near</b> the metro station. <b>There are</b> two supermarkets and a pharmacy <b>in front of</b> the house, but <b>there aren't any</b> cafés in our street. That's the only problem!</p></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Новые слова</h4><ul><li>a floor — этаж</li><li>a wall — стена</li><li>a building — здание</li><li>the only — единственный</li><li>a problem — проблема</li></ul></div></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 9: there is / there are и предлоги места</span></div>","groups":[{"title":"Правда или нет?","items":[{"t":"choice","q":"They live on the fourth floor.","o":["True","False"],"a":"True","ex":"on the fourth floor."},{"t":"choice","q":"There is a table in the living room.","o":["True","False"],"a":"False","ex":"There isn't a table in this room."},{"t":"choice","q":"There are cafés in their street.","o":["True","False"],"a":"False","ex":"There aren't any cafés in our street."},{"t":"choice","q":"The building is near the metro.","o":["True","False"],"a":"True","ex":"Our building is near the metro station."}]},{"title":"Ответьте по тексту","items":[{"t":"choice","q":"How many rooms are there in the flat?","o":["Three.","Two.","Four."],"a":"Three.","ex":"There are three rooms."},{"t":"choice","q":"Where is the TV?","o":["On the wall, opposite the sofa.","Next to the lamp.","In the kitchen."],"a":"On the wall, opposite the sofa.","ex":"Our TV is on the wall, opposite the sofa."},{"t":"choice","q":"Where do they have dinner?","o":["In the kitchen.","In the living room.","In a café."],"a":"In the kitchen.","ex":"we have dinner in the kitchen."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«В квартире три комнаты.»","a":["There are three rooms in the flat.","There are three rooms in the apartment."],"ex":"three rooms → There are.","p":"Переведите на английский"},{"t":"input","q":"«Рядом с диваном есть лампа.»","a":["There is a lamp next to the sofa.","There's a lamp next to the sofa."],"ex":"There is + next to.","p":"Переведите на английский"},{"t":"input","q":"«В нашей улице нет кафе.»","a":["There aren't any cafés in our street.","There are not any cafes in our street.","There aren't any cafes in our street."],"ex":"aren't any + cafés.","p":"Переведите на английский"}]}]},{"id":"day","nav":"Текст 3 · день","eyebrow":"Текст 3 · уроки 4–5","title":"Sergey's day","theory":"<h3>Sergey, a taxi driver</h3>\n<div class=\"reading\"><p>Sergey <b>is</b> a taxi driver in Moscow. He <b>works</b> five days a week and he <b>starts</b> work at two o'clock in the afternoon.</p><p>He <b>gets up</b> at ten, <b>has</b> a shower and <b>makes</b> breakfast for his family. Then he <b>takes</b> his son to school. He <b>doesn't have</b> lunch at home — he usually <b>eats</b> a sandwich in the car.</p><p>Sergey <b>finishes</b> work at midnight. He <b>gets</b> home at about one o'clock and <b>watches</b> TV for half an hour. He <b>goes</b> to bed at two. He <b>likes</b> his job, but he <b>doesn't like</b> the traffic.</p></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Новые слова</h4><ul><li>a taxi driver — таксист</li><li>midnight — полночь</li><li>half an hour — полчаса</li><li>traffic — пробки, движение</li></ul></div></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 4: привычки · Урок 5: -s у he / she / it и распорядок дня</span></div>","groups":[{"title":"Правда или нет?","items":[{"t":"choice","q":"Sergey starts work in the morning.","o":["True","False"],"a":"False","ex":"He starts work at two in the afternoon."},{"t":"choice","q":"He has lunch at home.","o":["True","False"],"a":"False","ex":"He doesn't have lunch at home."},{"t":"choice","q":"He takes his son to school.","o":["True","False"],"a":"True","ex":"Then he takes his son to school."},{"t":"choice","q":"He goes to bed at two.","o":["True","False"],"a":"True","ex":"He goes to bed at two."}]},{"title":"Ответьте по тексту","items":[{"t":"choice","q":"What time does he get up?","o":["At ten.","At two.","At midnight."],"a":"At ten.","ex":"He gets up at ten."},{"t":"choice","q":"Where does he usually eat lunch?","o":["In the car.","At home.","In a café."],"a":"In the car.","ex":"he usually eats a sandwich in the car."},{"t":"choice","q":"What doesn't he like?","o":["The traffic.","His job.","TV."],"a":"The traffic.","ex":"he doesn't like the traffic."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Он работает пять дней в неделю.»","a":["He works five days a week."],"ex":"he → works.","p":"Переведите на английский"},{"t":"input","q":"«Он не обедает дома.»","a":["He doesn't have lunch at home.","He does not have lunch at home."],"ex":"doesn't have lunch.","p":"Переведите на английский"},{"t":"input","q":"«Во сколько он заканчивает работу?»","a":["What time does he finish work?","When does he finish work?"],"ex":"What time + does + he + finish work?","p":"Переведите на английский"}]}]},{"id":"weekend","nav":"Текст 4 · выходные","eyebrow":"Текст 4 · урок 7","title":"Last weekend","theory":"<h3>A message from a friend</h3>\n<div class=\"reading\"><p>Hi! How <b>was</b> your weekend? Mine <b>was</b> great.</p><p>On Saturday morning I <b>got up</b> late and <b>had</b> a big breakfast. Then I <b>met</b> my friends in the centre and we <b>went</b> to a new café. The coffee <b>was</b> excellent, but the cake <b>wasn't</b> very good.</p><p>In the evening we <b>watched</b> a film at home. I <b>didn't go</b> out on Sunday, because the weather <b>was</b> terrible. I <b>stayed</b> at home and <b>read</b> a book. What <b>did</b> you <b>do</b>?</p></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Новые слова</h4><ul><li>mine — мой (без предмета)</li><li>the centre — центр города</li><li>excellent — отличный</li><li>terrible — ужасный</li><li>to stay — оставаться</li></ul></div></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 7: was / were, -ed, неправильные глаголы, didn't</span></div>","groups":[{"title":"Правда или нет?","items":[{"t":"choice","q":"He got up early on Saturday.","o":["True","False"],"a":"False","ex":"I got up late."},{"t":"choice","q":"The coffee in the café was good.","o":["True","False"],"a":"True","ex":"The coffee was excellent."},{"t":"choice","q":"He went out on Sunday.","o":["True","False"],"a":"False","ex":"I didn't go out on Sunday."},{"t":"choice","q":"The weather was bad on Sunday.","o":["True","False"],"a":"True","ex":"the weather was terrible."}]},{"title":"Ответьте по тексту","items":[{"t":"choice","q":"Where did he meet his friends?","o":["In the centre.","At home.","In the park."],"a":"In the centre.","ex":"I met my friends in the centre."},{"t":"choice","q":"What did they do in the evening?","o":["They watched a film.","They went to a café.","They read a book."],"a":"They watched a film.","ex":"we watched a film at home."},{"t":"choice","q":"Why didn't he go out on Sunday?","o":["Because the weather was terrible.","Because he was ill.","Because he was at work."],"a":"Because the weather was terrible.","ex":"because the weather was terrible."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Как прошли твои выходные?»","a":["How was your weekend?"],"ex":"How + was + your weekend?","p":"Переведите на английский"},{"t":"input","q":"«Мы сходили в новое кафе.»","a":["We went to a new café.","We went to a new cafe."],"ex":"go → went.","p":"Переведите на английский"},{"t":"input","q":"«В воскресенье я не выходил из дома.»","a":["I didn't go out on Sunday.","I did not go out on Sunday."],"ex":"didn't + go out.","p":"Переведите на английский"},{"t":"input","q":"«Погода была ужасная.»","a":["The weather was terrible."],"ex":"weather = it → was.","p":"Переведите на английский"}]}]},{"id":"cafe","nav":"Текст 5 · в кафе","eyebrow":"Текст 5 · уроки 10 и 12","title":"In a café","theory":"<h3>A conversation</h3>\n<div class=\"reading\"><p>— Good morning! What would you like?</p><p>— Good morning. <b>Can I have</b> a coffee and a cheese sandwich, please?</p><p>— Sure. <b>Would you like</b> anything else?</p><p>— Yes, <b>I'd like</b> a bottle of water too. And <b>can you</b> tell me the wi-fi password?</p><p>— Of course, it's on the menu. <b>That's</b> £8.40, please.</p><p>— Here you are. Thank you!</p></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Новые слова</h4><ul><li>a password — пароль</li><li>of course — конечно</li><li>anything else — что-нибудь ещё</li><li>Here you are — вот, пожалуйста</li></ul></div></div>\n<div class=\"sticky\"><span class=\"tag\">Связь с курсом</span><span>Урок 10: Can I…? и Can you…? · Урок 12: I'd like и цены</span></div>","groups":[{"title":"Правда или нет?","items":[{"t":"choice","q":"The customer orders tea.","o":["True","False"],"a":"False","ex":"Can I have a coffee…"},{"t":"choice","q":"The customer wants water too.","o":["True","False"],"a":"True","ex":"I'd like a bottle of water too."},{"t":"choice","q":"The wi-fi password is on the menu.","o":["True","False"],"a":"True","ex":"it's on the menu."}]},{"title":"Выберите фразу","items":[{"t":"choice","q":"Вежливо попросить кофе:","o":["Can I have a coffee, please?","I want a coffee.","Give me a coffee."],"a":"Can I have a coffee, please?","ex":"Can I have…? — вежливая просьба."},{"t":"choice","q":"Спросить, сколько всего:","o":["How much is that altogether?","How many is that?","What is the money?"],"a":"How much is that altogether?","ex":"How much + altogether."},{"t":"choice","q":"Попросить о помощи:","o":["Can you help me, please?","Can I help you, please?","Do you can help me?"],"a":"Can you help me, please?","ex":"Can you…? — просьба к собеседнику."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Можно мне кофе и бутерброд, пожалуйста?»","a":["Can I have a coffee and a sandwich, please?"],"ex":"Can I have + a coffee and a sandwich.","p":"Переведите на английский"},{"t":"input","q":"«Я бы хотел бутылку воды.»","a":["I'd like a bottle of water.","I would like a bottle of water."],"ex":"I'd like + a bottle of water.","p":"Переведите на английский"},{"t":"input","q":"«Сколько с меня?»","a":["How much is that?","How much is it?","How much is that altogether?"],"ex":"How much is that?","p":"Переведите на английский"}]}]},{"id":"mix","nav":"Текст 6 · всё вместе","eyebrow":"Текст 6 · весь курс","title":"A letter from Nick","theory":"<h3>Nick, 34, London</h3>\n<div class=\"reading\"><p>Hi! <b>I'm</b> Nick and I <b>live</b> in London with my wife and two children. I <b>work</b> as a journalist, so I <b>write</b> a lot every day.</p><p>We<b>'ve got</b> a small house near a park. <b>There's</b> a garden behind the house and my children <b>love</b> playing there. Right now they <b>are playing</b> football with our dog!</p><p>I usually <b>get up</b> at seven, but last Saturday I <b>got up</b> at eleven, because we <b>had</b> a party on Friday night. It <b>was</b> my wife's birthday. We <b>didn't cook</b> — we <b>ordered</b> pizza and <b>watched</b> films.</p><p>I <b>can't</b> cook very well, but I <b>can</b> make good coffee. Come and visit us — I<b>'d like</b> to show you the city!</p></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Новые слова</h4><ul><li>a wife — жена</li><li>to order — заказывать</li><li>to show — показать</li><li>Come and visit us — приезжайте в гости</li></ul></div></div>\n<p>Этот текст собран из всех тем курса: to be, have got, there is, Present Simple и Continuous, Past Simple, can и I'd like.</p>","groups":[{"title":"Правда или нет?","items":[{"t":"choice","q":"Nick lives in London.","o":["True","False"],"a":"True","ex":"I live in London."},{"t":"choice","q":"He has got a big flat.","o":["True","False"],"a":"False","ex":"We've got a small house."},{"t":"choice","q":"His children are playing football now.","o":["True","False"],"a":"True","ex":"Right now they are playing football."},{"t":"choice","q":"They cooked dinner for the party.","o":["True","False"],"a":"False","ex":"We didn't cook — we ordered pizza."},{"t":"choice","q":"Nick can cook very well.","o":["True","False"],"a":"False","ex":"I can't cook very well."}]},{"title":"Найдите время в предложении","items":[{"t":"choice","q":"«I work as a journalist» — это про…","o":["постоянную работу","сейчас","прошлое"],"a":"постоянную работу","ex":"Present Simple — постоянно."},{"t":"choice","q":"«They are playing football» — это про…","o":["сейчас","каждый день","прошлое"],"a":"сейчас","ex":"Present Continuous — прямо сейчас."},{"t":"choice","q":"«We ordered pizza» — это про…","o":["прошлое","сейчас","планы"],"a":"прошлое","ex":"Past Simple."},{"t":"choice","q":"«I can make good coffee» — это про…","o":["умение","прошлое","сейчас"],"a":"умение","ex":"can — умение."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«У нас есть маленький дом.»","a":["We've got a small house.","We have got a small house.","We have a small house."],"ex":"have got / have.","p":"Переведите на английский"},{"t":"input","q":"«За домом есть сад.»","a":["There is a garden behind the house.","There's a garden behind the house."],"ex":"There is + behind.","p":"Переведите на английский"},{"t":"input","q":"«В прошлую субботу я встал в одиннадцать.»","a":["Last Saturday I got up at eleven.","I got up at eleven last Saturday."],"ex":"get up → got up.","p":"Переведите на английский"},{"t":"input","q":"«Я не умею хорошо готовить.»","a":["I can't cook very well.","I cannot cook very well.","I can't cook well."],"ex":"can't + cook.","p":"Переведите на английский"},{"t":"input","q":"«Я бы хотел показать вам город.»","a":["I'd like to show you the city.","I would like to show you the city."],"ex":"I'd like + to show.","p":"Переведите на английский"}]}]}]}$lesson$::jsonb)
